import{_ as t,o as a,c as d,a2 as i}from"./chunks/framework.Ky-Ipuyb.js";const u=JSON.parse('{"title":"ImGui API 使用指南","description":"","frontmatter":{"lang":"zh-CN","sourcePath":"docs/imgui/api.zh-CN.md"},"headers":[],"relativePath":"zh/imgui/api.md","filePath":"zh/imgui/api.md"}'),o={name:"zh/imgui/api.md"};function r(c,e,l,n,h,s){return a(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="imgui-api-使用指南" tabindex="-1">ImGui API 使用指南 <a class="header-anchor" href="#imgui-api-使用指南" aria-label="Permalink to &quot;ImGui API 使用指南&quot;">​</a></h1><p>通过任务式教程理解用法后，用 <a href="/zh/reference/imgui/" target="_self">API 参考</a>核对参数和返回值。总览摘要帮助定位操作，详情页提供使用说明、参数、返回值和原生资源有效期。</p><h2 id="找到正确入口" tabindex="-1">找到正确入口 <a class="header-anchor" href="#找到正确入口" aria-label="Permalink to &quot;找到正确入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>入口</th><th>教程</th></tr></thead><tbody><tr><td>集成原生窗口</td><td><code>SFML.Init</code>、<code>ProcessEvent</code>、<code>Update</code>、<code>Render</code>、<code>Shutdown</code></td><td><a href="/zh/imgui/getting-started">快速开始</a></td></tr><tr><td>声明控件</td><td><code>ImGui.Button</code>、<code>Checkbox</code>、<code>SliderFloatEx</code></td><td><a href="/zh/imgui/widgets">控件</a></td></tr><tr><td>组织面板</td><td><code>BeginChild</code>、<code>BeginTable</code>、菜单与弹窗函数</td><td><a href="/zh/imgui/layout">布局</a></td></tr><tr><td>编辑 UTF-8、传入回调</td><td><code>InputTextEx</code>、<code>ListBoxCallbackEx</code>、<code>PlotLinesCallbackEx</code></td><td><a href="/zh/imgui/callbacks">回调</a></td></tr><tr><td>加载字体、修改样式</td><td>顶层 <code>getFontAtlas</code>、<code>getStyleColors</code>；<code>SFML.GetStyle</code></td><td><a href="/zh/imgui/fonts">字体</a></td></tr><tr><td>绘制图元、切换窗口</td><td><code>ImGui.GetWindowDrawList</code>、<code>SFML.SetCurrentWindow</code></td><td><a href="/zh/imgui/rendering">渲染</a></td></tr></tbody></table><h2 id="把签名读成-javascript-契约" tabindex="-1">把签名读成 JavaScript 契约 <a class="header-anchor" href="#把签名读成-javascript-契约" aria-label="Permalink to &quot;把签名读成 JavaScript 契约&quot;">​</a></h2><p>例如 <a href="/zh/reference/imgui/functions/ImGui.SliderFloatEx.html" target="_self">SliderFloatEx</a>接收可写 Float32Array、两个数值边界、格式字符串和标志，布尔返回值表示是否编辑，当前值从数组中读取。原生参数名不会让 JavaScript 数字具备写回能力。</p><p>重载名称明确区分：Button 使用默认尺寸，ButtonEx 接受大小；PushStyleVar 接受标量，PushStyleVarVec2 接受向量。Ex 不总是表示「带回调」，应查看具体签名。</p><p><code>ImVec2Like</code> 接受 <code>[ x, y ]</code> 或 <code>{ x, y }</code> 等向量值；可写数值指针则要求该函数声明的类型化数组。<code>ImGuiInputTextCallbackData</code> 等结构体句柄是绑定返回的带类型标记的不透明对象。纹理 ID 和原始指针参数使用 <code>bigint</code>，与结构体句柄不能互换，也不能猜测地址来构造。</p><p><code>ImGui.GetIO()</code>、<code>ImGui.GetStyle()</code> 返回原生句柄；<code>SFML.GetIO()</code>、<code>SFML.GetStyle()</code> 返回当前窗口的便捷可写字段视图。要求句柄的辅助函数不能接收便捷视图。</p><h2 id="调用前核对" tabindex="-1">调用前核对 <a class="header-anchor" href="#调用前核对" aria-label="Permalink to &quot;调用前核对&quot;">​</a></h2><ol><li>是否要求已初始化的上下文、活动帧或可见父窗口。</li><li>参数会被复制、原地修改，还是仅借用。</li><li>可选 null 是否关闭某项功能，例如窗口关闭按钮。</li><li>布尔返回值表示激活、编辑、选择，还是可见性。</li><li>需要哪一个 End/Pop，以及何时必须调用。</li><li>返回句柄和视图的有效期。</li></ol><p>源码声明便于 TypeScript 工具提示和实现核对：<a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/index.ts" target="_blank" rel="noreferrer">包导出</a>、<a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/sfml.ts" target="_blank" rel="noreferrer">SFML 集成</a>、<a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/src/imgui/index.ts" target="_blank" rel="noreferrer">ImGui 模块</a>。</p><p>API 说明紧贴声明维护，包含英、中、日、韩四语摘要与详情，由 TypeDoc 直接读取。反馈文档问题时，请提供准确函数、语言、预期 JavaScript 调用和实际结果。</p>',13)])])}const p=t(o,[["render",r]]);export{u as __pageData,p as default};
